def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return float(min(budget, base))

    opp_bids = []
    urgent_opp_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            opp_bids.append(float(bid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp_bids.append(float(bid))

    if opp_bids:
        highest_prev = max(opp_bids)
        avg_prev = sum(opp_bids) / float(len(opp_bids))
    else:
        highest_prev = DAILY_SALARY * 0.7
        avg_prev = DAILY_SALARY * 0.6

    if urgent_opp_bids:
        pressure_bid = max(highest_prev, max(urgent_opp_bids) + 1.0)
    else:
        pressure_bid = highest_prev + 1.5

    if supply <= 16:
        scarcity = 'high'
    elif supply <= 19:
        scarcity = 'medium'
    else:
        scarcity = 'low'

    if hp <= 2 or no_water_days >= 2:
        if scarcity == 'high':
            bid = max(pressure_bid, DAILY_SALARY * 0.96)
        elif scarcity == 'medium':
            bid = max(pressure_bid, DAILY_SALARY * 0.88)
        else:
            bid = max(avg_prev + 2.0, DAILY_SALARY * 0.78)
    elif hp <= 4 or no_water_days >= 1:
        if scarcity == 'high':
            bid = max(pressure_bid, DAILY_SALARY * 0.86)
        elif scarcity == 'medium':
            bid = max(avg_prev + 1.5, DAILY_SALARY * 0.72)
        else:
            bid = max(avg_prev, DAILY_SALARY * 0.58)
    else:
        if scarcity == 'high':
            bid = max(avg_prev, DAILY_SALARY * 0.62)
        elif scarcity == 'medium':
            bid = max(avg_prev - 3.0, DAILY_SALARY * 0.48)
        else:
            bid = DAILY_SALARY * 0.28

    if day >= 8 and hp >= 5 and no_water_days == 0:
        bid *= 0.9

    reserve_floor = 0.0
    if day <= 5:
        reserve_floor = DAILY_SALARY * 2.2
    elif day <= 8:
        reserve_floor = DAILY_SALARY * 1.2
    max_affordable = budget
    if budget > reserve_floor:
        max_affordable = budget - reserve_floor + min(reserve_floor * 0.15, DAILY_SALARY * 0.5)

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    if hp >= 6 and no_water_days == 0 and scarcity == 'low':
        bid = min(bid, DAILY_SALARY * 0.35)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 40.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    if not yesterday_bids:
        return min(my_status['budget'], 60.0)
    avg_prev = sum(yesterday_bids) / len(yesterday_bids)
    if my_status['hp'] <= 3:
        return min(my_status['budget'], 75.0)
    bid = min(my_status['budget'], max(65.0, avg_prev + 2.0))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Get yesterday's highest bid among alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']

    # Base bid: if we urgently need water, bid high; otherwise, try to save
    if hp <= 2:
        # Very low HP, must win water at almost any cost
        target = min(budget, DAILY_SALARY * 0.95)
        if yesterday_bids:
            target = min(budget, max(target, max(yesterday_bids) + 5.0))
        return target
    elif hp <= 4:
        # Low HP, need water but can be moderate
        if yesterday_bids:
            target = min(budget, max(DAILY_SALARY * 0.6, max(yesterday_bids) + 1.0))
        else:
            target = min(budget, DAILY_SALARY * 0.6)
        return target
    else:
        # Healthy - try to save money by bidding low, but not too low
        if yesterday_bids:
            target = min(budget, min(DAILY_SALARY * 0.45, max(yesterday_bids) - 2.0))
            # Ensure we don't bid too low if supply is scarce
            if supply < (MIN_SUPPLY + MAX_SUPPLY) / 2:
                target = min(budget, max(target, DAILY_SALARY * 0.35))
        else:
            target = min(budget, DAILY_SALARY * 0.35)
        return max(target, 1.0)  # Always bid at least 1 to avoid zero bid (unless budget is 0)
